// ilans.net/cv - generated by ~/cv-drafts/cv-build/build.py, edit there.
(function () {
  // ---------- theme toggle, same storage key as the rest of ilans.net
  var root = document.documentElement;
  var meta = document.getElementById('themeColorMeta');
  var btn = document.getElementById('themeToggle');
  function apply(light) {
    if (light) root.setAttribute('data-theme', 'light'); else root.removeAttribute('data-theme');
    if (meta) meta.setAttribute('content', light ? '#faf9f7' : '#0b0b0d');
    if (btn) btn.setAttribute('aria-pressed', light ? 'true' : 'false');
  }
  apply(root.getAttribute('data-theme') === 'light');
  if (btn) btn.addEventListener('click', function () {
    var light = root.getAttribute('data-theme') !== 'light';
    apply(light);
    try { localStorage.setItem('theme', light ? 'light' : 'dark'); } catch (e) {}
  });

  // ---------- live status: every app is pinged from the visitor's browser.
  // no-cors gives an opaque response - it proves the host answered, not the status code.
  var cards = Array.prototype.slice.call(document.querySelectorAll('.app[data-url]'));
  var sum = document.getElementById('liveSum');
  var done = 0, live = 0;

  function report() {
    if (!sum) return;
    sum.textContent = done < cards.length
      ? 'checking ' + (cards.length - done) + ' of ' + cards.length + '...'
      : live + ' of ' + cards.length + ' responding now';
  }

  function ping(card) {
    var ctl = 'AbortController' in window ? new AbortController() : null;
    var timer = setTimeout(function () { if (ctl) ctl.abort(); }, 8000);
    return fetch(card.getAttribute('data-url'), {
      mode: 'no-cors', cache: 'no-store', signal: ctl ? ctl.signal : undefined
    }).then(function () {
      card.setAttribute('data-status', 'live'); live++;
      card.querySelector('.state').textContent = 'live';
    }, function () {
      card.setAttribute('data-status', 'unreachable');
      card.querySelector('.state').textContent = 'no response from this browser';
    }).then(function () {
      clearTimeout(timer); done++; report();
      if (done === cards.length) {
        window.__appsUp = live;
        document.querySelectorAll('[data-up]').forEach(function (n) { n.textContent = live; });
      }
    });
  }

  report();
  cards.forEach(ping);
})();

// ---------- portrait turntable behind the apps grid.
// cv.json lists views for one side (angle, size, skull axis); the other side is the same view mirrored.
// Each view is shown for the slice of the turn nearest its angle, so gaps between angles just hold longer.
(function () {
  var box = document.querySelector('.turntable[data-turntable]');
  if (!box) return;
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var cfg;
  try { cfg = JSON.parse(box.getAttribute('data-turntable')); } catch (e) { return; }

  var W = cfg.W, views = [];
  cfg.frames.forEach(function (f) {
    views.push({ f: f, angle: f.angle, mirror: false });
    if (f.angle !== 0 && Math.abs(f.angle) !== 180) views.push({ f: f, angle: -f.angle, mirror: true });
  });

  var first = box.querySelector('img');
  function place(img, v) {
    var ax = v.mirror ? v.f.w - v.f.ax : v.f.ax;
    img.style.left = ((W / 2 - ax) / W * 100).toFixed(3) + '%';
    img.style.width = (v.f.w / W * 100).toFixed(3) + '%';
    img.style.transform = v.mirror ? 'scaleX(-1)' : '';
  }

  // one <img> per view, stacked; only the current one is visible (no src swapping, no decode flicker)
  var imgs = views.map(function (v) {
    var img = new Image();
    img.alt = ''; img.decoding = 'async'; img.src = v.f.file;
    place(img, v); img.style.visibility = 'hidden';
    return img;
  });

  function nearest(deg) {
    var best = 0, bestD = 1e9;
    views.forEach(function (v, i) {
      var d = Math.abs(((deg - v.angle) % 360 + 540) % 360 - 180);
      if (d < bestD) { bestD = d; best = i; }
    });
    return best;
  }

  var shown = -1, running = false, visible = true, t0 = null, spent = 0;
  function show(i) {
    if (i === shown) return;
    if (shown >= 0) imgs[shown].style.visibility = 'hidden';
    imgs[i].style.visibility = 'visible';
    shown = i;
  }
  // living grain: a new noise pattern a few times a second (cv.json portrait.grain.fps)
  var noise = document.getElementById('tt-noise'), grainEvery = cfg.grainFps ? 1000 / cfg.grainFps : 0,
      grainAt = 0, seed = 1;

  // signal-loss bursts (cv.json portrait.glitch): for a fraction of a second the image tears sideways,
  // the grain spikes and the portrait flashes brighter, at random 1-2.5 s gaps so it never feels metronomic
  var G = cfg.glitch, tear = document.getElementById('tt-tear'), bands = document.getElementById('tt-bands'),
      ct = document.getElementById('tt-ct'), funcs = ct ? ct.children : [], calm = null,
      burstUntil = 0, nextBurst = 0;
  if (G && tear && ct) {
    calm = [].map.call(funcs, function (f) { return [f.getAttribute('slope'), f.getAttribute('intercept')]; });
  }
  // outside control (the ask box): face the visitor, think, speak. views[0] is the -15 view, the most frontal.
  var mode = { attend: false, thinking: false, level: 0 }, speaking = false,
      calmOpacity = parseFloat(getComputedStyle(box).opacity) || 0.22;
  window.ttControl = {
    attend: function (on) {
      if (mode.attend && !on) { spent = (15 / 360) * cfg.seconds * 1000; t0 = null; }   // resume from the front
      mode.attend = !!on;
    },
    thinking: function (on) { mode.thinking = !!on; nextBurst = 0; },
    level: function (v) { mode.level = Math.max(0, Math.min(1, +v || 0)); }
  };

  // t = 0 calm grain, 1 full burst; anything between follows a voice
  function grainMix(t) {
    [].forEach.call(funcs, function (f, i) {
      var cs = +calm[i][0];
      if (f.tagName === 'feFuncA') { f.setAttribute('slope', cs + (G.strength - cs) * t); return; }
      var ci = +(calm[i][1] || 0), si = -(G.contrast - 1) / 2 + (G.bias || 0);
      f.setAttribute('slope', cs + (G.contrast - cs) * t);
      // bias < 0 pushes the noise below mid-grey, so a burst darkens instead of flashing white
      f.setAttribute('intercept', ci + (si - ci) * t);
    });
  }
  function calmDown() {
    tear.setAttribute('scale', 0); grainMix(0);
    box.style.opacity = ''; box.style.transform = '';
  }
  function glitch(now) {
    if (!calm) return;
    if (mode.level > 0.03) {                                    // speaking: the signal follows the voice
      var v = mode.level;
      tear.setAttribute('scale', (G.tear * 0.5 * v).toFixed(1));
      bands.setAttribute('seed', Math.floor(Math.random() * 999) + 1);
      grainMix(Math.min(1, v * 1.2));
      box.style.opacity = (calmOpacity + (G.opacity - calmOpacity) * v).toFixed(3);
      speaking = true; burstUntil = 0;
      return;
    }
    if (speaking) { speaking = false; calmDown(); nextBurst = 0; }
    var lo = mode.thinking ? 0.18 : G.every_min, hi = mode.thinking ? 0.6 : G.every_max;
    if (!nextBurst) nextBurst = now + 1000 * (lo + Math.random() * (hi - lo));
    if (now >= nextBurst && !burstUntil) {                      // start a burst, each one a different length
      burstUntil = now + (mode.thinking ? 0.12 : G.duration) * 1000 * (0.6 + Math.random() * 0.8);
      grainMix(1);
      box.style.opacity = G.opacity;
    }
    if (burstUntil) {
      if (now < burstUntil) {                                   // jitter while it lasts
        tear.setAttribute('scale', (G.tear * (0.65 + Math.random() * 0.35)).toFixed(1));
        bands.setAttribute('seed', Math.floor(Math.random() * 999) + 1);
        box.style.transform = 'translate(calc(-50% + ' + ((Math.random() * 2 - 1) * G.jump).toFixed(1) + 'px), -50%)';
      } else {                                                  // back to calm
        burstUntil = 0;
        // sometimes the signal drops twice in a row, like a real bad antenna
        nextBurst = Math.random() < (G.double || 0) ? now + 150 + Math.random() * 250 : 0;
        calmDown();
      }
    }
  }
  function frame(now) {
    if (!running) return;
    if (noise && grainEvery && now - grainAt >= grainEvery) {
      grainAt = now; seed = seed % 997 + 1; noise.setAttribute('seed', seed);
    }
    glitch(now);
    if (mode.attend) {                                          // facing the visitor, not turning
      t0 = null; show(0);
    } else {
      if (t0 === null) t0 = now - spent;
      spent = now - t0;
      var deg = -((spent / 1000) / cfg.seconds * 360) % 360;    // turns the same way as the source views
      show(nearest(deg));
    }
    requestAnimationFrame(frame);
  }
  function update() {
    var go = visible && !document.hidden;
    if (go && !running) { running = true; t0 = null; requestAnimationFrame(frame); }
    if (!go) running = false;
  }

  Promise.all(imgs.map(function (img) {
    return img.decode ? img.decode().catch(function () {}) : Promise.resolve();
  })).then(function () {
    imgs.forEach(function (img) { box.appendChild(img); });
    if (first) first.remove();
    show(nearest(views[0].angle));
    if ('IntersectionObserver' in window) {
      new IntersectionObserver(function (es) { visible = es[0].isIntersecting; update(); }).observe(box);
    }
    document.addEventListener('visibilitychange', update);
    update();
  });
})();


// ---------- a link made for one company: ilans.net/cv/#for=<base64 json> (build.py --link).
// The fragment never reaches a server, so no public file lists who Ilan is talking to.
(function () {
  var m = /[#&]for=([A-Za-z0-9_-]+)/.exec(location.hash);
  if (!m) return;
  var spec;
  try {
    var b = m[1].replace(/-/g, '+').replace(/_/g, '/');
    while (b.length % 4) b += '=';
    spec = JSON.parse(decodeURIComponent(escape(atob(b))));
  } catch (e) { return; }
  if (!spec || !spec.c) return;

  var h1 = document.querySelector('header.hero h1');
  if (h1) {
    var tag = document.createElement('div'), who = document.createElement('b');
    tag.className = 'prepared';
    tag.appendChild(document.createTextNode('Prepared for '));
    who.textContent = spec.c; tag.appendChild(who);
    if (spec.r) tag.appendChild(document.createTextNode(' · ' + spec.r));
    h1.insertAdjacentElement('afterend', tag);
  }
  var list = document.querySelector('.apps');                 // most relevant work first
  if (list && spec.t && spec.t.length) {
    [].slice.call(list.children).map(function (li, i) {
      var tags = (li.getAttribute('data-tags') || '').split(' ');
      return { li: li, i: i, s: spec.t.filter(function (t) { return tags.indexOf(t) >= 0; }).length };
    }).sort(function (a, b) { return b.s - a.s || a.i - b.i; })
      .forEach(function (x) { list.appendChild(x.li); });
  }
  if (spec.v && /^ilan-lenzner-cv[\w-]*\.pdf$/.test(spec.v)) {
    var dl = document.querySelector('.actions a[download]');
    if (dl) dl.setAttribute('href', spec.v);
  }
  var ta = document.getElementById('askText');
  if (ta && !ta.value) {
    ta.value = spec.r ? 'Is Ilan a fit for the ' + spec.r + ' role at ' + spec.c + '?'
                      : 'Is Ilan a fit for ' + spec.c + '?';
  }
  document.title = 'CV - Ilan Lenzner, for ' + spec.c;
})();

// ---------- ask his AI: the same honest role-fit agent as the ilans.net widget, streamed in place.
// The portrait turns to face the visitor, glitches while it thinks, and its signal follows the voice.
(function () {
  var form = document.querySelector('.ask-form');
  if (!form) return;
  var api = form.getAttribute('data-api'), ta = document.getElementById('askText'),
      thread = document.getElementById('askThread'), btn = form.querySelector('button[type=submit]'),
      history = [], idleTimer = null;
  function tt(fn, v) { if (window.ttControl) window.ttControl[fn](v); }
  function settleSoon(ms) { clearTimeout(idleTimer); idleTimer = setTimeout(function () { tt('attend', false); }, ms); }

  [].forEach.call(document.querySelectorAll('[data-ask]'), function (a) {
    a.addEventListener('click', function (e) {
      e.preventDefault();
      document.getElementById('ask').scrollIntoView({ behavior: 'smooth', block: 'start' });
      setTimeout(function () { ta.focus({ preventScroll: true }); }, 450);
    });
  });

  function strip(t) { return t.replace(/\[\[[^\]]*\]\]/g, '').replace(/[ \t]+\n/g, '\n').trim(); }
  function linkify(el, text) {
    el.textContent = '';
    var re = /(https?:\/\/[^\s)]+|[\w.+-]+@[\w-]+\.[\w.]+|\b(?:[a-z0-9-]+\.)+(?:net|com|org|io|ai|app|cloud|dev)(?:\/[^\s)]*)?)/gi,
        last = 0, m;
    while ((m = re.exec(text))) {
      var u = m[0].replace(/[.,;:!?]+$/, '');
      el.appendChild(document.createTextNode(text.slice(last, m.index)));
      var a = document.createElement('a');
      a.textContent = u;
      a.href = /^https?:/.test(u) ? u : (/@/.test(u) ? 'mailto:' + u : 'https://' + u);
      if (!/^mailto:/.test(a.href)) { a.target = '_blank'; a.rel = 'noopener'; }
      el.appendChild(a);
      last = m.index + u.length;
    }
    el.appendChild(document.createTextNode(text.slice(last)));
  }
  function bubble(cls, text) {
    var d = document.createElement('div');
    d.className = cls;
    if (text) d.textContent = text;
    thread.appendChild(d);
    return d;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var q = ta.value.trim();
    if (!q || btn.disabled) return;
    if (history.length >= 22) history = history.slice(-20);
    history.push({ role: 'user', content: q });
    bubble('ask-q', q);
    var a = bubble('ask-a thinking', 'Thinking...'), answer = '';
    ta.value = ''; btn.disabled = true;
    clearTimeout(idleTimer); tt('attend', true); tt('thinking', true);

    fetch(api + '/chat', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ messages: history })
    }).then(function (res) {
      if (!res.ok) {
        return res.json().catch(function () { return {}; }).then(function (d) {
          throw new Error(d.error || 'The AI is not answering right now - the real one is at ilan@ilans.net.');
        });
      }
      var reader = res.body.getReader(), dec = new TextDecoder(), buf = '';
      function pump() {
        return reader.read().then(function (step) {
          if (step.done) return;
          buf += dec.decode(step.value, { stream: true });
          var lines = buf.split('\n');
          buf = lines.pop();
          lines.forEach(function (line) {
            if (line.indexOf('data: ') !== 0) return;
            try {
              var ev = JSON.parse(line.slice(6));
              if (ev.type === 'content_block_delta' && ev.delta && ev.delta.text) {
                if (!answer) { a.classList.remove('thinking'); tt('thinking', false); }
                answer += ev.delta.text;
                a.textContent = strip(answer);
              }
            } catch (err) {}
          });
          return pump();
        });
      }
      return pump();
    }).then(function () {
      tt('thinking', false);
      if (!answer) throw new Error('No answer this time - try again, or write to ilan@ilans.net.');
      var clean = strip(answer);
      history.push({ role: 'assistant', content: clean });
      linkify(a, clean);
      var tools = document.createElement('div');
      tools.className = 'tools';
      if (clean.length <= 1600) {
        var say = document.createElement('button');
        say.type = 'button'; say.textContent = 'Hear it in his voice';
        say.addEventListener('click', function () { speak(clean, say); });
        tools.appendChild(say);
      }
      a.appendChild(tools);
      if (/\[\[lead\]\]/.test(answer)) a.appendChild(leadForm());
      settleSoon(9000);
    }).catch(function (err) {
      tt('thinking', false);
      a.classList.remove('thinking');
      a.textContent = err.message;
      history.pop();
      settleSoon(3000);
    }).then(function () { btn.disabled = false; });
  });

  ta.addEventListener('keydown', function (e) {                 // Cmd/Ctrl+Enter sends
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
      e.preventDefault();
      if (form.requestSubmit) form.requestSubmit(); else btn.click();
    }
  });

  var ctx = null, current = null;
  function speak(text, button) {
    if (current) { current.pause(); current = null; tt('level', 0); }
    button.disabled = true; button.textContent = 'Getting his voice...';
    clearTimeout(idleTimer); tt('attend', true);
    try {                                                       // create/resume inside the click, while it counts as a gesture
      ctx = ctx || new (window.AudioContext || window.webkitAudioContext)();
      if (ctx.state === 'suspended') ctx.resume();
    } catch (e) { ctx = null; }
    fetch(api + '/tts', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text: text })
    }).then(function (r) {
      if (!r.ok) throw new Error('voice');
      return r.blob();
    }).then(function (blob) {
      var audio = new Audio(URL.createObjectURL(blob));
      current = audio;
      if (ctx) {
        var an = ctx.createAnalyser(), data = new Uint8Array(512);
        an.fftSize = 512;
        ctx.createMediaElementSource(audio).connect(an);
        an.connect(ctx.destination);
        audio.addEventListener('playing', function loop() {
          if (audio.paused || audio.ended) { tt('level', 0); return; }
          an.getByteTimeDomainData(data);
          var sum = 0;
          for (var i = 0; i < data.length; i++) { var x = (data[i] - 128) / 128; sum += x * x; }
          tt('level', Math.min(1, Math.sqrt(sum / data.length) * 4));
          requestAnimationFrame(loop);
        });
      }
      audio.addEventListener('ended', function () {
        tt('level', 0); current = null;
        button.disabled = false; button.textContent = 'Hear it again';
        settleSoon(4000);
      });
      button.textContent = 'Speaking...';
      return audio.play();
    }).catch(function () {
      tt('level', 0);
      button.disabled = false; button.textContent = 'Voice unavailable right now';
      settleSoon(3000);
    });
  }

  function leadForm() {
    var f = document.createElement('form');
    f.className = 'lead';
    f.innerHTML = '<input name="name" placeholder="Your name" required autocomplete="name">' +
                  '<input name="email" type="email" placeholder="Email" required autocomplete="email">' +
                  '<textarea name="note" rows="2" placeholder="Role or project, in a line (optional)"></textarea>' +
                  '<button class="btn primary" type="submit">Send to Ilan</button>';
    f.addEventListener('submit', function (e) {
      e.preventDefault();
      var fd = new FormData(f), sb = f.querySelector('button');
      sb.disabled = true; sb.textContent = 'Sending...';
      fetch(api + '/lead', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: fd.get('name'), email: fd.get('email'), note: fd.get('note') })
      }).then(function (r) {
        if (!r.ok) throw new Error();
        f.innerHTML = '<span class="ok">Sent - Ilan gets it right away.</span>';
      }).catch(function () {
        sb.disabled = false; sb.textContent = 'Did not go through - try again, or ilan@ilans.net';
      });
    });
    return f;
  }
})();

// App hover loops: a short muted clip of the app floats above its card while hovered.
// It arrives and leaves through a TV signal-loss burst (same recipe as the portrait: sideways tear,
// grain spike, a flash and a jump), drops out again at the loop seam and now and then while it plays.
// Built lazily on first hover; desktop pointers only, never with reduced motion.
(() => {
  if (!matchMedia('(hover: hover) and (pointer: fine)').matches) return;
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const INTENT_MS = 160;              // passing across the grid should not flash previews
  const G = { tear: 46, contrast: 6, bias: -0.35, flash: 0.45, jump: 6, every: [1.6, 4.2] };
  const NS = 'http://www.w3.org/2000/svg';
  const rnd = (a, b) => a + Math.random() * (b - a);
  let uid = 0;

  // one filter per card, so a preview leaving and the next arriving never share a burst
  function makeFilter() {
    const id = 'peek-g' + (++uid), k = G.contrast, ic = -(k - 1) / 2 + G.bias;
    const svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('class', 'peek-defs'); svg.setAttribute('aria-hidden', 'true');
    svg.innerHTML =
      `<filter id="${id}" x="-8%" y="0" width="116%" height="100%" color-interpolation-filters="sRGB">` +
      '<feTurbulence type="turbulence" baseFrequency="0.0008 0.07" numOctaves="1" seed="2" result="bands"/>' +
      '<feDisplacementMap in="SourceGraphic" in2="bands" scale="0" xChannelSelector="R" yChannelSelector="A" result="torn"/>' +
      '<feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed="1" stitchTiles="stitch" result="noise"/>' +
      '<feColorMatrix in="noise" type="saturate" values="0" result="mono"/>' +
      `<feComponentTransfer in="mono" result="grain"><feFuncR type="linear" slope="${k}" intercept="${ic}"/>` +
      `<feFuncG type="linear" slope="${k}" intercept="${ic}"/><feFuncB type="linear" slope="${k}" intercept="${ic}"/>` +
      '<feFuncA type="linear" slope="0"/></feComponentTransfer>' +
      '<feBlend in="grain" in2="torn" mode="hard-light"/></filter>';
    document.body.append(svg);
    const q = (sel) => svg.querySelector(sel);
    return { id, bands: q('feTurbulence[result="bands"]'), tear: q('feDisplacementMap'),
             noise: q('feTurbulence[result="noise"]'), alpha: q('feFuncA') };
  }

  for (const li of document.querySelectorAll('.app[data-clip]')) {
    let v = null, f = null, timer = 0, raf = 0;
    let burst = null, nextAt = 0, lastT = 0;

    // k: 0..1 strength. decay: fades out over the burst (arrival) instead of jittering at full strength
    const start = (ms, k, decay) => { burst = { t0: performance.now(), ms, k, decay }; loop(); };
    const calm = () => {
      f.tear.setAttribute('scale', 0); f.alpha.setAttribute('slope', 0);
      v.style.filter = ''; v.style.transform = '';
    };
    function tick(now) {
      raf = 0;
      const live = li.classList.contains('peeking');
      if (live && !v.paused) {
        if (v.currentTime + 0.5 < lastT) start(rnd(160, 260), 0.85);          // the loop seam
        lastT = v.currentTime;
        if (!nextAt) nextAt = now + 1000 * rnd(...G.every);
        if (!burst && now >= nextAt) { start(rnd(90, 220), rnd(0.55, 1)); nextAt = 0; }
      }
      if (burst) {
        const p = (now - burst.t0) / burst.ms;
        if (p >= 1) { burst = null; calm(); }
        else {
          const k = burst.decay ? burst.k * (1 - p) * (1 - p) : burst.k;
          f.tear.setAttribute('scale', (G.tear * k * rnd(0.6, 1)).toFixed(1));
          f.bands.setAttribute('seed', (Math.random() * 999 | 0) + 1);
          f.noise.setAttribute('seed', (Math.random() * 999 | 0) + 1);
          f.alpha.setAttribute('slope', k.toFixed(2));
          v.style.filter = `url(#${f.id}) brightness(${(1 + G.flash * k * Math.random()).toFixed(2)})`;
          v.style.transform = `translateX(${(rnd(-1, 1) * G.jump * k).toFixed(1)}px)`;
        }
      }
      if (live || burst) loop();
    }
    const loop = () => { if (!raf) raf = requestAnimationFrame(tick); };

    const prepare = () => {            // runs during the intent wait, so loading never stalls the entrance
      if (v) return;
      const peek = document.createElement('span');
      peek.className = 'peek';
      peek.setAttribute('aria-hidden', 'true');
      v = document.createElement('video');
      Object.assign(v, { muted: true, loop: true, playsInline: true, preload: 'auto' });
      v.poster = li.dataset.clip + '.jpg';
      v.src = li.dataset.clip + '.webm';
      f = makeFilter();
      peek.append(v);
      li.append(peek);
      peek.getBoundingClientRect();   // commit the hidden state first, or the first entrance skips its transition
    };
    const show = () => {
      li.classList.add('peeking');
      v.currentTime = 0; lastT = 0; nextAt = 0;
      v.play().catch(() => {});
      start(420, 1, true);             // the signal locks on
    };
    li.addEventListener('pointerenter', () => { prepare(); timer = setTimeout(show, INTENT_MS); });
    li.addEventListener('pointerleave', () => {
      clearTimeout(timer);
      if (!li.classList.contains('peeking')) return;
      li.classList.remove('peeking');
      start(200, 0.9);                 // and drops out
      setTimeout(() => { if (!li.classList.contains('peeking')) v.pause(); }, 260);
    });
  }
})();


// Stat cubes: every few seconds the four stats roll forward in a wave, the next fact coming up
// from the bottom face. Facts come from cv.json proof[].more. Pauses on hover, offscreen and in
// background tabs; with reduced motion the first faces just stay.
(() => {
  const row = document.querySelector('.stats[data-every]');
  if (!row || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const every = +row.dataset.every * 1000, stagger = +row.dataset.stagger * 1000;
  const cubes = [...row.querySelectorAll('.stat[data-faces]')].map((st) => {
    const faces = [st.querySelector('.face').innerHTML, ...JSON.parse(st.dataset.faces)];
    return { st, cube: st.querySelector('.cube'), front: st.querySelector('.face'), faces, i: 0 };
  });
  if (!cubes.length) return;
  // Sizes stay exactly what the first facts give: measure the row with the first faces, lock the
  // column widths and tile heights, and let any longer fact shrink its type to fit instead.
  function lock() {
    const now = cubes.map((c) => c.front.innerHTML);
    cubes.forEach((c) => { c.front.innerHTML = fresh(c.faces[0]); c.st.style.height = ''; fit(c.front, true); });
    row.style.gridTemplateColumns = '';
    const cols = getComputedStyle(row).gridTemplateColumns;
    if (cols && cols !== 'none') row.style.gridTemplateColumns = cols;
    cubes.forEach((c, k) => {
      c.st.style.height = c.st.offsetHeight + 'px';
      c.st.style.setProperty('--half', c.st.offsetHeight / 2 + 'px');
      c.front.innerHTML = now[k]; fit(c.front);
    });
  }
  function fit(face, reset) {
    for (const el of face.querySelectorAll(':scope > b, :scope > span')) {
      el.style.fontSize = '';
      if (reset) continue;
      const room = face.clientWidth - parseFloat(getComputedStyle(face).paddingLeft) * 2;
      if (el.scrollWidth > room) {
        const px = parseFloat(getComputedStyle(el).fontSize);
        el.style.fontSize = Math.max(px * 0.7, px * room / el.scrollWidth - 0.2).toFixed(1) + 'px';
      }
    }
  }
  let rs = 0;
  addEventListener('resize', () => { clearTimeout(rs); rs = setTimeout(lock, 120); });

  const fresh = (html) => html.replace(/(<span data-up>)\d+/g, (m, open) => open + (window.__appsUp ?? m.slice(open.length)));
  lock();
  if (document.fonts) document.fonts.ready.then(lock);   // web fonts change the widths
  function roll(c) {
    if (c.cube.classList.contains('rolling')) return;
    c.i = (c.i + 1) % c.faces.length;
    const next = document.createElement('div');
    next.className = 'face next';
    next.innerHTML = fresh(c.faces[c.i]);
    c.cube.append(next);
    fit(next);
    next.getBoundingClientRect();
    c.cube.classList.add('rolling');
    c.cube.addEventListener('transitionend', function done(e) {
      if (e.target !== c.cube) return;
      c.cube.removeEventListener('transitionend', done);
      c.front.innerHTML = next.innerHTML;          // the bottom face becomes the front, cube snaps back unseen
      fit(c.front);
      next.remove();
      c.cube.classList.remove('rolling');
    });
  }

  let hover = false, seen = false, timer = 0;
  row.addEventListener('pointerenter', () => { hover = true; });
  row.addEventListener('pointerleave', () => { hover = false; });
  new IntersectionObserver((es) => { seen = es[0].isIntersecting; }).observe(row);
  function wave() {
    if (!hover && seen && !document.hidden) cubes.forEach((c, k) => setTimeout(() => roll(c), k * stagger));
    timer = setTimeout(wave, every);
  }
  timer = setTimeout(wave, every);
})();
